import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardMedia,
  Typography,
  Container,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  LinearProgress,
  styled,
} from '@mui/material';
import { Movement, GameState, LeaderboardEntry, OptionState } from '../types';
import { initializeMovements, initializeGame, handleAnswer, updateTimer, saveToLeaderboard, getLeaderboard } from '../utils';

interface Props {
  movements: string[];
}

interface StyledButtonProps {
  isSelected?: boolean;
  isCorrect?: boolean;
}

const StyledButton = styled(Button, {
  shouldForwardProp: (prop) => prop !== 'isSelected' && prop !== 'isCorrect',
})<StyledButtonProps>(({ isSelected, isCorrect }) => ({
  height: '60px',
  fontSize: '1.1rem',
  textTransform: 'none',
  transition: 'all 0.3s ease',
  backgroundColor: isSelected 
    ? (isCorrect ? '#4caf50' : '#f44336')
    : '#1976d2',
  color: '#ffffff',
  '&:hover': {
    transform: 'scale(1.02)',
    boxShadow: '0 4px 8px rgba(0,0,0,0.1)',
    backgroundColor: isSelected 
      ? (isCorrect ? '#4caf50' : '#f44336')
      : '#1976d2',
  },
  '&.Mui-disabled': {
    backgroundColor: isCorrect ? '#4caf50' : '#f44336',
    color: '#ffffff',
    opacity: 1,
  },
}));

const MemoryGame: React.FC<Props> = ({ movements }) => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [movementList, setMovementList] = useState<Movement[]>([]);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [leaderboard, setLeaderboard] = useState<{ entries: LeaderboardEntry[] }>({ entries: [] });

  useEffect(() => {
    const initializedMovements = initializeMovements(movements);
    setMovementList(initializedMovements);
    setGameState(initializeGame(initializedMovements));
    setLeaderboard(getLeaderboard());
  }, [movements]);

  useEffect(() => {
    if (!gameState || gameState.isGameOver) return;

    const timer = setInterval(() => {
      setGameState(prev => {
        if (!prev) return null;
        return updateTimer(prev, movementList);
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState, movementList]);

  const handleOptionClick = (selectedAnswer: string) => {
    if (!gameState) return;
    setGameState(prev => {
      if (!prev) return null;
      const newState = handleAnswer(prev, selectedAnswer, movementList);
      if (newState.isGameOver) {
        saveToLeaderboard(newState.score, 30 * newState.totalQuestions - newState.timeLeft);
        setLeaderboard(getLeaderboard());
      }
      return newState;
    });
  };

  const handleRestart = () => {
    setGameState(initializeGame(movementList));
  };

  if (!gameState) return null;

  if (gameState.isGameOver) {
    return (
      <Container maxWidth="md" sx={{ mt: 4 }}>
        <Paper elevation={3} sx={{ p: 4, textAlign: 'center' }}>
          <Typography variant="h4" gutterBottom>
            Game Over!
          </Typography>
          <Typography variant="h5" gutterBottom>
            Your Score: {gameState.score} / {gameState.totalQuestions}
          </Typography>
          <Button variant="contained" color="primary" onClick={handleRestart} sx={{ mt: 2 }}>
            Play Again
          </Button>
          <Button
            variant="outlined"
            color="primary"
            onClick={() => setShowLeaderboard(!showLeaderboard)}
            sx={{ mt: 2, ml: 2 }}
          >
            {showLeaderboard ? 'Hide Leaderboard' : 'Show Leaderboard'}
          </Button>
          
          {showLeaderboard && (
            <TableContainer component={Paper} sx={{ mt: 4 }}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Rank</TableCell>
                    <TableCell>Score</TableCell>
                    <TableCell>Time</TableCell>
                    <TableCell>Date</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {leaderboard.entries.map((entry, index) => (
                    <TableRow key={index}>
                      <TableCell>{index + 1}</TableCell>
                      <TableCell>{entry.score}</TableCell>
                      <TableCell>{entry.time}s</TableCell>
                      <TableCell>{entry.date}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Paper>
      </Container>
    );
  }

  return (
    <Container maxWidth="md" sx={{ mt: 4 }}>
      <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
        <Typography variant="h3" component="h1" gutterBottom>
          Pilates Quiz Game
        </Typography>
        <Typography variant="h6" gutterBottom>
          Score: {gameState.score} | Question: {gameState.currentQuestion}/{gameState.totalQuestions}
        </Typography>
        <Box sx={{ width: '100%', mb: 2 }}>
          <LinearProgress 
            variant="determinate" 
            value={(gameState.timeLeft / 30) * 100} 
            color={gameState.timeLeft <= 10 ? "error" : "primary"}
          />
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            Time Left: {gameState.timeLeft} seconds
          </Typography>
        </Box>

        <Card sx={{ maxWidth: 400, width: '100%' }}>
          <CardMedia
            component="img"
            height="300"
            image={gameState.currentMovement.image}
            alt={gameState.currentMovement.name}
            sx={{ objectFit: 'contain' }}
          />
        </Card>

        <Box sx={{ 
          display: 'grid', 
          gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, 1fr)' },
          gap: 2,
          width: '100%',
          maxWidth: 600
        }}>
          {gameState.options.map((option, index) => (
            <StyledButton
              key={index}
              variant="contained"
              fullWidth
              onClick={() => handleOptionClick(option.text)}
              disabled={option.isSelected || option.isCorrect}
              isSelected={option.isSelected}
              isCorrect={option.isCorrect}
            >
              {option.text}
            </StyledButton>
          ))}
        </Box>
      </Box>
    </Container>
  );
};

export default MemoryGame; 