import { Movement, GameState, LeaderboardEntry, OptionState } from './types';

export const initializeMovements = (movements: string[]): Movement[] => {
  // 隨機打亂圖片順序
  const shuffledIndices = Array.from({ length: movements.length }, (_, i) => i + 1)
    .sort(() => Math.random() - 0.5);
  
  return movements.map((name, index) => ({
    id: shuffledIndices[index],
    image: process.env.PUBLIC_URL + `/pilates-images/${shuffledIndices[index]}.png`,
    name,
  }));
};

export const getRandomOptions = (movements: Movement[], correctAnswer: string, count: number = 4): OptionState[] => {
  const otherMovements = movements.filter(m => m.name !== correctAnswer);
  const shuffled = [...otherMovements].sort(() => Math.random() - 0.5);
  const options = shuffled.slice(0, count - 1).map(m => ({ text: m.name }));
  options.push({ text: correctAnswer });
  return options.sort(() => Math.random() - 0.5);
};

export const initializeGame = (movements: Movement[]): GameState => {
  // 隨機打亂題目順序
  const shuffledMovements = [...movements].sort(() => Math.random() - 0.5);
  const currentMovement = shuffledMovements[0];
  
  return {
    currentMovement,
    options: getRandomOptions(movements, currentMovement.name),
    score: 0,
    timeLeft: 30,
    isGameOver: false,
    totalQuestions: movements.length,
    currentQuestion: 1,
    feedback: {
      show: false,
      isCorrect: false,
      message: '',
    },
  };
};

export const handleAnswer = (state: GameState, selectedAnswer: string, movements: Movement[]): GameState => {
  const isCorrect = selectedAnswer === state.currentMovement?.name;
  const newScore = isCorrect ? state.score + 1 : state.score;
  const nextQuestionIndex = state.currentQuestion;
  
  // Update options with feedback
  const updatedOptions = state.options.map(option => ({
    ...option,
    isSelected: option.text === selectedAnswer,
    isCorrect: option.text === state.currentMovement.name,
  }));

  if (nextQuestionIndex >= state.totalQuestions) {
    return {
      ...state,
      options: updatedOptions,
      score: newScore,
      isGameOver: true,
    };
  }

  const nextMovement = movements[nextQuestionIndex];
  return {
    ...state,
    currentMovement: nextMovement,
    options: getRandomOptions(movements, nextMovement.name),
    score: newScore,
    currentQuestion: state.currentQuestion + 1,
    timeLeft: 30,
  };
};

export const updateTimer = (state: GameState, movements: Movement[]): GameState => {
  if (state.timeLeft <= 0) {
    if (state.currentQuestion >= state.totalQuestions) {
      // Show correct answer when time's up
      const updatedOptions = state.options.map(option => ({
        ...option,
        isCorrect: option.text === state.currentMovement.name,
      }));

      return {
        ...state,
        options: updatedOptions,
        isGameOver: true,
      };
    }

    const nextMovement = movements[state.currentQuestion];
    return {
      ...state,
      currentMovement: nextMovement,
      options: getRandomOptions(movements, nextMovement.name),
      currentQuestion: state.currentQuestion + 1,
      timeLeft: 30,
    };
  }

  return {
    ...state,
    timeLeft: state.timeLeft - 1,
  };
};

// 排行榜相關函數
export const saveToLeaderboard = (score: number, time: number): void => {
  const leaderboard = getLeaderboard();
  const newEntry: LeaderboardEntry = {
    score,
    time,
    date: new Date().toLocaleString(),
  };
  
  leaderboard.entries.push(newEntry);
  leaderboard.entries.sort((a, b) => b.score - a.score || a.time - b.time);
  leaderboard.entries = leaderboard.entries.slice(0, 10); // 只保留前10名
  
  localStorage.setItem('pilatesGameLeaderboard', JSON.stringify(leaderboard));
};

export const getLeaderboard = (): { entries: LeaderboardEntry[] } => {
  const saved = localStorage.getItem('pilatesGameLeaderboard');
  return saved ? JSON.parse(saved) : { entries: [] };
}; 